/**
 * Runtime secrets for the API Worker on a self-hosted celld box.
 *
 * celld has no secret mechanism, and whatever is in a deployment's `vars` is stored in plaintext
 * in the fleet bucket for every version. So on a box the deploy passes no secret at all: the
 * Worker gets them at runtime from the box-local key agent (deploy/selfhost/key-agent), which
 * opens the sealed bundle with the operator's key service. They live only in this isolate's
 * memory.
 *
 * Only the celld entry module (generated by scripts/selfhost/celld-project.ts) imports this file,
 * through runtime-secrets-socket.ts, which supplies the `cloudflare:sockets` connect (this module
 * takes it injected so the deploy's contract check can run it under Node, secrets-preflight.ts).
 * The Cloudflare build's entry is `src/index.ts`, which does not, so Cloudflare installs keep
 * their Worker secret bindings and never run this code.
 *
 * Channel: a raw TCP socket (`cloudflare:sockets`) to the agent on 127.0.0.1, not HTTP. The
 * request starts with KEY_AGENT_PREAMBLE, whose first byte is NUL; every HTTP request starts with
 * a method token, so no `fetch` the Worker can be steered into (any URL, headers, body, redirect
 * or DNS answer) can ask the agent for secrets (finding F9: with HTTP, the bundle id, which sits
 * in the bucket's deploy vars, was enough for an SSRF that could set headers and a body). The
 * agent also checks the peer's uid (only celld's) and signs its answer over our nonce.
 *
 * Cost: one loopback round trip per cold request, until one succeeds and the isolate caches the
 * answer (celld retires idle stateless isolates every 30 s pool tick). If the agent is down the
 * Worker fails closed: HTTP 503 `SECRETS_UNAVAILABLE`, a failed cron run, a Durable Object that
 * refuses its events. Nothing runs without its secrets.
 *
 * Why every caller makes its own request instead of joining one in flight: celld 0.6.3 gives an
 * async op to the request that started it and drops it when that request's client disconnects. A
 * shared in-flight load started by a request whose client then gave up never settles, so every
 * request that joined it hung until its own client gave up or celld's 300 s handler budget ran
 * out (scripts/selfhost/live/shared-flight-cancel.live.test.ts). The agent caches the opened
 * bundle, so a concurrent cold burst costs one signature per request.
 */

import { log } from '../lib/logger';
import { type JsonRecord, maybeJsonRecord } from '../lib/runtime-validation';
import {
  enableSelfHostRotationScope,
  setPreviousEncryptionKeys,
} from '../services/encryption-key-fallback';
import { type AesKeyEnv, previousKeyPairs } from './key-rotation/keys';
import {
  encodeKeyAgentFrame,
  readFrame,
  RuntimeSecretsUnavailableError,
} from './runtime-secrets-frame';

export {
  encodeKeyAgentFrame,
  KEY_AGENT_PREAMBLE,
  MAX_KEY_AGENT_RESPONSE_BYTES,
  RuntimeSecretsUnavailableError,
} from './runtime-secrets-frame';

export const DEFAULT_KEY_AGENT_TIMEOUT_MS = 3000;
/**
 * How long an isolate keeps the secrets before asking the agent again (SAM_RUNTIME_SECRETS_TTL_MS).
 * Bounds how long a revoked key service, or a replaced bundle, keeps serving a long-lived isolate:
 * once due, an agent that refuses or cannot prove itself fails the request; only an unreachable
 * agent lets the isolate keep its copy (an agent restart must not take SAM down).
 */
export const DEFAULT_RUNTIME_SECRETS_TTL_MS = 5 * 60_000;
/**
 * The longest an isolate serves its copy past the TTL while the agent stays unreachable
 * (SAM_RUNTIME_SECRETS_MAX_STALE_MS), counted from when it was loaded. Matches the agent's own
 * SAM_KEY_AGENT_MAX_STALE_SECONDS default: past it the copy is dropped and requests fail closed,
 * so a stopped agent cannot keep revoked credentials alive in a busy isolate indefinitely.
 */
export const DEFAULT_RUNTIME_SECRETS_MAX_STALE_MS = 6 * 60 * 60_000;
const AGENT_ADDRESS = /^127\.0\.0\.1:(\d{1,5})$/;
const BUNDLE_ID = /^[0-9a-f]{32}$/;
const SECRET_NAME = /^[A-Z_][A-Z0-9_]*$/;

export interface KeyAgentEnv {
  /** `127.0.0.1:<port>`, the agent's loopback socket; written by the self-host deploy. */
  SAM_KEY_AGENT_ADDRESS?: string;
  /** The sealed bundle this deployment was built with; a content-free random id. */
  SAM_SECRET_BUNDLE_ID?: string;
  /** Raw Ed25519 public key (base64) the agent's answers must verify under. Not a secret. */
  SAM_KEY_AGENT_VERIFY_KEY?: string;
  /** Bound into the request: the agent refuses a bundle sealed for another install. */
  SAM_INSTALLATION_ID?: string;
  SAM_KEY_AGENT_TIMEOUT_MS?: string;
  SAM_RUNTIME_SECRETS_TTL_MS?: string;
  SAM_RUNTIME_SECRETS_MAX_STALE_MS?: string;
}

/** Names the agent's answer may never set: the channel's own settings. */
const PROTECTED_NAMES = new Set([
  'SAM_KEY_AGENT_ADDRESS',
  'SAM_SECRET_BUNDLE_ID',
  'SAM_KEY_AGENT_VERIFY_KEY',
  'SAM_KEY_AGENT_TIMEOUT_MS',
  'SAM_RUNTIME_SECRETS_TTL_MS',
  'SAM_RUNTIME_SECRETS_MAX_STALE_MS',
  'SAM_INSTALLATION_ID',
]);

export type RuntimeSecrets = Readonly<Record<string, string>>;

/** The slice of a `cloudflare:sockets` socket this loader uses. */
export interface KeyAgentSocket {
  readonly readable: ReadableStream<Uint8Array>;
  readonly writable: WritableStream<Uint8Array>;
  close(): Promise<void>;
}

/** `cloudflare:sockets` connect, or an equivalent (Node under the deploy's contract check). */
export type KeyAgentConnect = (address: { hostname: string; port: number }) => KeyAgentSocket;

const NO_SOCKET: KeyAgentConnect = () => {
  throw new Error('no key-agent socket configured');
};
let connectSocket: KeyAgentConnect = NO_SOCKET;
/**
 * `loadedAt`: when this isolate fetched the copy (the TTL counts from it). `openedAt`: when the
 * agent opened it, earlier than `loadedAt` when the agent answered from a stale copy while the key
 * service was down (the stale bound counts from it, so the two stale windows never add up).
 */
let cached: {
  bundleId: string;
  secrets: RuntimeSecrets;
  loadedAt: number;
  openedAt: number;
} | null = null;
/** A resident object's background refresh in flight (residentSecret), or null. */
let backgroundRefresh: Promise<unknown> | null = null;

/** Sets how this isolate reaches the agent (runtime-secrets-socket.ts on celld). */
export function useKeyAgentSocket(socket: KeyAgentConnect): void {
  connectSocket = socket;
}

/** For tests: forget this isolate's copy, as a fresh isolate would, and set the socket. */
export function resetRuntimeSecretsForTests(socket?: KeyAgentConnect): void {
  cached = null;
  backgroundRefresh = null;
  connectSocket = socket ?? NO_SOCKET;
}

interface AgentSettings {
  hostname: string;
  port: number;
  bundleId: string;
  verifyKey: Uint8Array;
  installationId: string;
  timeoutMs: number;
}

function settings(env: KeyAgentEnv): AgentSettings {
  const address = AGENT_ADDRESS.exec(env.SAM_KEY_AGENT_ADDRESS ?? '');
  const port = Number(address?.[1] ?? 0);
  const bundleId = env.SAM_SECRET_BUNDLE_ID ?? '';
  let verifyKey = new Uint8Array();
  try {
    verifyKey = Uint8Array.from(atob(env.SAM_KEY_AGENT_VERIFY_KEY ?? ''), (c) => c.charCodeAt(0));
  } catch {
    // reported below
  }
  if (
    !address ||
    port < 1 ||
    port > 65535 ||
    !BUNDLE_ID.test(bundleId) ||
    verifyKey.length !== 32
  ) {
    throw new RuntimeSecretsUnavailableError(
      'SECRETS_MISCONFIGURED',
      'SAM_KEY_AGENT_ADDRESS must be 127.0.0.1:<port>, SAM_SECRET_BUNDLE_ID a bundle id ' +
        'and SAM_KEY_AGENT_VERIFY_KEY an Ed25519 public key'
    );
  }
  const timeout = Number.parseInt(env.SAM_KEY_AGENT_TIMEOUT_MS ?? '', 10);
  return {
    hostname: '127.0.0.1',
    port,
    bundleId,
    verifyKey,
    installationId: env.SAM_INSTALLATION_ID ?? '',
    timeoutMs:
      Number.isSafeInteger(timeout) && timeout > 0 ? timeout : DEFAULT_KEY_AGENT_TIMEOUT_MS,
  };
}

function hex(bytes: Uint8Array): string {
  return [...bytes].map((b) => b.toString(16).padStart(2, '0')).join('');
}

async function verifySignature(
  key: Uint8Array,
  signature: unknown,
  body: string
): Promise<boolean> {
  if (typeof signature !== 'string' || signature === '') return false;
  try {
    const sig = Uint8Array.from(atob(signature), (c) => c.charCodeAt(0));
    const publicKey = await crypto.subtle.importKey('raw', key, { name: 'Ed25519' }, false, [
      'verify',
    ]);
    return await crypto.subtle.verify(
      { name: 'Ed25519' },
      publicKey,
      sig,
      new TextEncoder().encode(body)
    );
  } catch {
    return false;
  }
}

function positiveMs(raw: string | undefined, fallback: number): number {
  const value = Number.parseInt(raw ?? '', 10);
  return Number.isSafeInteger(value) && value > 0 ? value : fallback;
}

function ttlMs(env: KeyAgentEnv): number {
  return positiveMs(env.SAM_RUNTIME_SECRETS_TTL_MS, DEFAULT_RUNTIME_SECRETS_TTL_MS);
}

function maxStaleMs(env: KeyAgentEnv): number {
  return positiveMs(env.SAM_RUNTIME_SECRETS_MAX_STALE_MS, DEFAULT_RUNTIME_SECRETS_MAX_STALE_MS);
}

/**
 * Age of this isolate's copy, or null when it has none. A clock that moved backwards gives a
 * negative age; that copy counts as expired, so a clock correction cannot stretch either bound.
 */
function cachedAgeMs(): number | null {
  return cached ? ageSince(cached.loadedAt) : null;
}

/** How long ago the agent opened this isolate's copy (the stale bound), as cachedAgeMs. */
function cachedStaleAgeMs(): number | null {
  return cached ? ageSince(cached.openedAt) : null;
}

function ageSince(at: number): number {
  const age = Date.now() - at;
  return age < 0 ? Number.POSITIVE_INFINITY : age;
}

/** This isolate's secrets if loaded for the deployment's bundle and not yet due, else null. */
export function cachedRuntimeSecrets(env: KeyAgentEnv): RuntimeSecrets | null {
  const age = cachedAgeMs();
  const staleAge = cachedStaleAgeMs();
  // Due at the TTL or the stale bound, whichever comes first: a TTL above the bound is capped.
  return cached &&
    cached.bundleId === env.SAM_SECRET_BUNDLE_ID &&
    age !== null &&
    staleAge !== null &&
    age < ttlMs(env) &&
    staleAge < maxStaleMs(env)
    ? cached.secrets
    : null;
}

/** One request/answer on a fresh socket, bounded by the agent timeout. */
async function exchange(agent: AgentSettings, request: string): Promise<string> {
  let socket: KeyAgentSocket;
  try {
    socket = connectSocket({ hostname: agent.hostname, port: agent.port });
  } catch (error) {
    throw new RuntimeSecretsUnavailableError(
      'KEY_AGENT_UNREACHABLE',
      `key agent unreachable (${error instanceof Error ? error.name : 'error'})`
    );
  }
  let timer: ReturnType<typeof setTimeout> | undefined;
  const timeout = new Promise<never>((_, reject) => {
    timer = setTimeout(
      () =>
        reject(
          new RuntimeSecretsUnavailableError(
            'KEY_AGENT_UNREACHABLE',
            `key agent did not answer within ${agent.timeoutMs} ms`
          )
        ),
      agent.timeoutMs
    );
  });
  const talk = async (): Promise<string> => {
    const writer = socket.writable.getWriter();
    try {
      await writer.write(encodeKeyAgentFrame(request));
    } finally {
      writer.releaseLock();
    }
    return await readFrame(socket.readable);
  };
  try {
    return await Promise.race([talk(), timeout]);
  } catch (error) {
    if (error instanceof RuntimeSecretsUnavailableError) throw error;
    throw new RuntimeSecretsUnavailableError(
      'KEY_AGENT_UNREACHABLE',
      `key agent unreachable (${error instanceof Error ? error.name : 'error'})`
    );
  } finally {
    clearTimeout(timer);
    socket.close().catch(() => undefined);
  }
}

function parseRecord(text: string): JsonRecord {
  try {
    return maybeJsonRecord(JSON.parse(text) as unknown) ?? {};
  } catch {
    // never repeat the parser's message: the text can carry the secrets
    return {};
  }
}

async function fetchSecrets(
  agent: AgentSettings
): Promise<{ secrets: RuntimeSecrets; ageMs: number }> {
  const started = Date.now();
  const nonce = hex(crypto.getRandomValues(new Uint8Array(16)));
  const envelope = parseRecord(
    await exchange(
      agent,
      JSON.stringify({
        op: 'secrets',
        bundleId: agent.bundleId,
        nonce,
        installationId: agent.installationId,
      })
    )
  );
  if (envelope.status !== 200 || typeof envelope.body !== 'string') {
    // Unsigned text from whoever holds the port: printable, short, never a log injection.
    const error =
      typeof envelope.error === 'string'
        ? ` ${envelope.error.replace(/[^\x20-\x7e]/g, '?').slice(0, 64)}`
        : '';
    throw new RuntimeSecretsUnavailableError(
      'KEY_AGENT_REFUSED',
      `key agent answered ${typeof envelope.status === 'number' ? envelope.status : 'malformed'}${error}`
    );
  }
  const text = envelope.body;
  // Whoever answers on the agent's port must prove it opened the bundle: a process that took the
  // port while the agent was down cannot sign this nonce.
  if (!(await verifySignature(agent.verifyKey, envelope.signature, text))) {
    throw new RuntimeSecretsUnavailableError(
      'KEY_AGENT_UNVERIFIED',
      "key agent answer is not signed by this deployment's agent key"
    );
  }
  const record = parseRecord(text);
  const secrets = record.secrets;
  // How old the agent's copy is (0 when fresh; an agent from before this field sends none).
  const ageMs = 'ageMs' in record ? record.ageMs : 0;
  if (
    typeof ageMs !== 'number' ||
    !Number.isFinite(ageMs) ||
    ageMs < 0 ||
    record.bundleId !== agent.bundleId ||
    record.nonce !== nonce ||
    typeof secrets !== 'object' ||
    secrets === null ||
    Array.isArray(secrets) ||
    Object.entries(secrets).some(
      ([k, v]) => !SECRET_NAME.test(k) || PROTECTED_NAMES.has(k) || typeof v !== 'string'
    )
  ) {
    throw new RuntimeSecretsUnavailableError(
      'KEY_AGENT_BAD_RESPONSE',
      'key agent response is malformed'
    );
  }
  log.info('runtime_secrets.loaded', {
    bundle: agent.bundleId.slice(0, 8),
    count: Object.keys(secrets).length,
    ms: Date.now() - started,
  });
  return { secrets: Object.freeze({ ...(secrets as Record<string, string>) }), ageMs };
}

/**
 * The deployment's secrets: from this isolate's memory, else one request to the key agent made by
 * this caller. Never joins another request's load (see the module comment). A failure is not
 * cached, so the next request retries (a refused connection fails in about a millisecond).
 */
export async function loadRuntimeSecrets(env: KeyAgentEnv): Promise<RuntimeSecrets> {
  const hit = cachedRuntimeSecrets(env);
  if (hit) return hit;
  const agent = settings(env);
  // Past the stale bound the copy is gone before the agent is asked: nothing can revive it.
  if ((cachedStaleAgeMs() ?? 0) >= maxStaleMs(env)) cached = null;
  let fetched: { secrets: RuntimeSecrets; ageMs: number };
  try {
    fetched = await fetchSecrets(agent);
  } catch (error) {
    // A due copy survives only an unreachable agent; a refusal or an unverified answer ends it.
    // The bound is checked again here: the failed attempt itself (up to SAM_KEY_AGENT_TIMEOUT_MS)
    // can carry the copy past it.
    if (
      cached?.bundleId === agent.bundleId &&
      error instanceof RuntimeSecretsUnavailableError &&
      error.code === 'KEY_AGENT_UNREACHABLE' &&
      (cachedStaleAgeMs() ?? Number.POSITIVE_INFINITY) < maxStaleMs(env)
    ) {
      return cached.secrets;
    }
    if (cached?.bundleId === agent.bundleId) cached = null;
    throw error;
  }
  // The agent's own stale bound can be longer than this one: an answer already older than ours is
  // refused, not cached, so it cannot be used again and again until the agent's bound ends.
  if (fetched.ageMs >= maxStaleMs(env)) {
    if (cached?.bundleId === agent.bundleId) cached = null;
    throw new RuntimeSecretsUnavailableError(
      'SECRETS_EXPIRED',
      `the key agent answered with a copy ${fetched.ageMs} ms old, past this Worker's stale bound`
    );
  }
  const loadedAt = Date.now();
  cached = {
    bundleId: agent.bundleId,
    secrets: fetched.secrets,
    loadedAt,
    openedAt: loadedAt - fetched.ageMs,
  };
  // Every load, a background refresh of a resident Durable Object included, re-registers the
  // rotation read fallback for the bundle it installed, so the map never lags the secrets.
  registerRotationKeys({ ...fetched.secrets });
  return fetched.secrets;
}

/**
 * `env` with the secrets laid over it: a new object, the runtime's env is never mutated. A secret
 * may replace a string var (as a secrets.env override did before), never a binding.
 */
export function withRuntimeSecrets<E extends object>(env: E, secrets: RuntimeSecrets): E {
  const merged: Record<string, unknown> = { ...(env as Record<string, unknown>) };
  for (const [name, value] of Object.entries(secrets)) {
    const existing = merged[name];
    if (existing === undefined || typeof existing === 'string') merged[name] = value;
  }
  registerRotationKeys(merged);
  return merged as E;
}

/**
 * Registers this bundle's previous AES keys, if a platform-key rotation is in progress
 * (`<NAME>_PREVIOUS`, key-rotation/keys.ts), as the read fallback of `decrypt` / `decryptFile`
 * (services/encryption-key-fallback.ts), and clears them when the bundle has none. Pure CPU: no
 * I/O. Also turns on the rotation scope, so the JWT and BetterAuth rotation variables are
 * honoured. Only this self-host module calls it, so on Cloudflare the scope stays off and the
 * fallback map empty.
 */
export function registerRotationKeys(env: Record<string, unknown>): void {
  enableSelfHostRotationScope();
  if (typeof env.ENCRYPTION_KEY !== 'string') return;
  setPreviousEncryptionKeys(previousKeyPairs(env as unknown as AesKeyEnv));
}

/** One refresh at a time for resident objects; its own timeout (exchange) always settles it. */
export function refreshInBackground(env: KeyAgentEnv): void {
  if (backgroundRefresh) return;
  backgroundRefresh = loadRuntimeSecrets(env)
    .catch(() => undefined)
    .finally(() => {
      backgroundRefresh = null;
    });
}

/**
 * This isolate's copy for the deployment's bundle with its age (a backwards clock counts as
 * expired), and the two bounds; for the Durable Object wrapper (runtime-secrets-durable-object.ts).
 */
export function currentRuntimeSecrets(env: KeyAgentEnv): {
  secrets: RuntimeSecrets | null;
  ageMs: number;
  staleAgeMs: number;
  ttlMs: number;
  maxStaleMs: number;
} {
  const age = cachedAgeMs();
  const current = cached?.bundleId === env.SAM_SECRET_BUNDLE_ID && age !== null ? cached : null;
  return {
    secrets: current ? current.secrets : null,
    ageMs: age ?? Number.POSITIVE_INFINITY,
    staleAgeMs: cachedStaleAgeMs() ?? Number.POSITIVE_INFINITY,
    ttlMs: ttlMs(env),
    maxStaleMs: maxStaleMs(env),
  };
}
